CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(30) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,balance DECIMAL(14,2) NOT NULL DEFAULT 0,role ENUM("user","admin") NOT NULL DEFAULT "user",status ENUM("active","blocked") NOT NULL DEFAULT "active",created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE services(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category VARCHAR(80) NOT NULL,name VARCHAR(190) NOT NULL,rate_per_1000 DECIMAL(12,4) NOT NULL,min_qty INT UNSIGNED DEFAULT 100,max_qty INT UNSIGNED DEFAULT 100000,status ENUM("active","inactive") DEFAULT "active",created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,service_id INT UNSIGNED NOT NULL,provider_order_id VARCHAR(100),link TEXT NOT NULL,quantity INT UNSIGNED NOT NULL,charge DECIMAL(14,2) NOT NULL,status ENUM("pending","processing","completed","partial","cancelled","refunded") DEFAULT "pending",created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(service_id) REFERENCES services(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,type ENUM("deposit","order","refund","adjustment","withdrawal") NOT NULL,amount DECIMAL(14,2) NOT NULL,description VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE deposits(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,amount DECIMAL(14,2) NOT NULL,method VARCHAR(50) NOT NULL,transaction_id VARCHAR(120) NOT NULL,status ENUM("pending","approved","rejected") DEFAULT "pending",reviewed_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE withdrawals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,amount DECIMAL(14,2) NOT NULL,method VARCHAR(50) NOT NULL,account VARCHAR(120) NOT NULL,status ENUM("pending","approved","rejected") DEFAULT "pending",reviewed_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE tickets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,subject VARCHAR(190) NOT NULL,message TEXT NOT NULL,status ENUM("open","closed") DEFAULT "open",created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
